/**
 * Shared writer for the custom-color scripts: serializes light + dark 12-step
 * scales to ui/src/css/custom/<name>.css as --<name>-1 … --<name>-12 custom
 * properties plus an alpha scale --<name>-a1 … --<name>-a12.
 *
 * Each block's alpha scale is step 9 at the given per-step opacity, so the
 * alpha ramp follows the same easing as that block's solid lightness ramp
 * (light: 1 − lum, distance below white; dark: darkLum, distance above
 * black). Values are gamut-mapped to display-p3.
 */
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

import type Color from "colorjs.io";

const outDir = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "../../../ui/src/css/custom",
);

export type ScaleBlock = {
  scale: Color[];
  /** Per-step opacity of the alpha scale (clamped to [0, 1]). */
  alphaOpacity: number[];
};

function toP3(color: Color): Color {
  const p3 = color.to("p3").toGamut({ space: "p3" });
  // Gamut mapping can leave coords a hair outside [0, 1]; clamp the residue.
  for (let c = 0; c < p3.coords.length; c++) {
    p3.coords[c] = Math.min(1, Math.max(0, p3.coords[c]));
  }
  return p3;
}

const serialize = (p3: Color) =>
  p3.toString({ precision: 5 }).replace("color(p3 ", "color(display-p3 ");

// The solid + alpha custom-property lines for one block (light or dark).
function scaleLines(name: string, { scale, alphaOpacity }: ScaleBlock) {
  const nine = toP3(scale[8]);
  return [
    ...scale.map((color, i) => `  --${name}-${i + 1}: ${serialize(toP3(color))};`),
    ``,
    ...scale.map((_, i) => {
      const step = nine.clone();
      step.alpha = Math.min(1, Math.max(0, alphaOpacity[i]));
      return `  --${name}-a${i + 1}: ${serialize(step)};`;
    }),
  ];
}

export async function writeScaleCss(
  name: string,
  generatedBy: string,
  light: ScaleBlock,
  dark: ScaleBlock,
) {
  const lines = [
    `/* AUTO-GENERATED by scripts/vendor/custom-color/${generatedBy} — do not edit by hand. */`,
    ``,
    `:root, .light, .light-theme {`,
    ...scaleLines(name, light),
    `}`,
    ``,
    `.dark, .dark-theme {`,
    ...scaleLines(name, dark),
    `}`,
    ``,
  ];
  await mkdir(outDir, { recursive: true });
  const outPath = path.join(outDir, `${name}.css`);
  await writeFile(outPath, lines.join("\n"));
  console.log(`Wrote ${path.relative(process.cwd(), outPath)}`);
}
